#Selects nodes by id (their tree path), e.g. an asset just added: the tree's selection and this view's copy of it, so a later
#click on the node that was selected before is a change and sends updatePopupSelection. Their parents are opened. The
#selection is set once every node is in the items, here or when they rebuild (custom.items onChange): set before, the
#browser drops it, and setting the same value again later wouldn't reach it.
def expandTo(view, ids):
	#Opens each node's parents in the items (a new node's parent may be collapsed, a leaf until now), so the node shows
	parents = set()
	for nodeId in ids:
		parts = nodeId.split('\\')
		for n in range(1, len(parts)): parents.add('\\'.join(parts[:n]))
	items = system.util.jsonDecode(system.util.jsonEncode(view.custom.items or []))
	changed = [False]
	def walk(level):
		for item in level:
			if item['id'] in parents and not item['expanded']:
				item['expanded'] = True
				changed[0] = True
			if item['children']: walk(item['children'])
	walk(items)
	if changed[0]: view.custom.items = items

if payload.has_key('msgHandler') and payload['msgHandler'] != self.view.params.values.msgHandler: return	#Meant for a different tree on this page
ids = [nodeId for nodeId in (payload['ids'] if payload.has_key('ids') else []) if nodeId]
if not ids: return
self.view.custom.pendingSelection = ids
expandTo(self.view, ids)
present = set()
def collect(level):
	for item in level or []:
		present.add(item['id'])
		if item['children']: collect(item['children'])
collect(system.util.jsonDecode(system.util.jsonEncode(self.view.custom.items or [])))
if self.view.custom.pendingSelection and all(nodeId in present for nodeId in ids):
	self.view.custom.pendingSelection = None
	self.view.custom.selectionPath = ids
	self.view.custom.selection = [{'itemPath': nodeId, 'value': {'path': nodeId}} for nodeId in ids]

return
